const parentEvidenceId = "ev_5cce3aafdc3f5d81d9fa8b02a33c22c2679d7d4f7274748aaf97d30184efe299";
const rows = [];
const evidence_ids = [];
let offset = 0;
let coverage = null;
for (;;) {
  const result = await rea.call("inspect_analysis_view", {
    source: { kind: "retained-evidence", evidence_id: parentEvidenceId },
    view: {
      kind: "javascript", collection: "modules", projection: "references",
      where: { path: "main.js", kind: "javascript-module" },
      offset, limit: 64
    }
  });
  if (!result.ok) throw new Error(JSON.stringify(result));
  const value = result.value;
  evidence_ids.push(value.evidence_id);
  rows.push(...value.normalized_result.rows);
  coverage = value.normalized_result.coverage;
  if (coverage.exhausted) break;
  offset = coverage.next_offset;
}
const external_specifiers = {};
for (const row of rows) {
  const id = row.identity;
  if (id.strategy === "artifact-local-key" && id.namespace === "unresolved-semantic-module" && id.key.startsWith("external:")) {
    external_specifiers[id.key.slice("external:".length)] = row.retained_source_range_count;
  }
}
print({
  module_identity_count: rows.length,
  external_module_count: Object.keys(external_specifiers).length,
  external_specifiers,
  inventory_exhausted: coverage.exhausted,
  query_evidence_ids: evidence_ids,
  source_coverage: value.normalized_result.source_coverage
});

